contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 burnAmount) public payable {
        require(burnAmount > 0);

        address ownerAddr = c.owner();
        uint256 balanceBefore = c.balanceOf(ownerAddr);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 balanceAfter = c.balanceOf(ownerAddr);
            uint256 supplyAfter = c.totalSupply();
            assert(balanceAfter == balanceBefore - burnAmount && supplyAfter == supplyBefore - burnAmount);
        } else {
            assert(burnAmount > balanceBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, bool freeze) public payable {
        require(target != address(0));

        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && c.frozenAccount(target) == freeze);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public {
        require(to == address(0));

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
        assert(c.balanceOf(address(this)) == senderBefore);
        assert(c.balanceOf(to) == 0);
        assert(c.totalSupply() == totalBefore);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 mintAmount, address to, uint256 transferAmount) public payable {
        require(target != address(0));
        require(to != address(0));

        // Record pre-mint values.
        uint256 preTotalSupply = c.totalSupply();
        uint256 preTargetBalance = c.balanceOf(target);
        uint256 preCallerBalance = c.balanceOf(address(this));

        // Mint: this contract is the owner since it deployed c.
        c.mintToken(target, mintAmount);

        // Read post-mint values.
        uint256 postTotalSupply = c.totalSupply();
        uint256 postTargetBalance = c.balanceOf(target);

        // Record pre-transfer values.
        uint256 preToBalance = c.balanceOf(to);

        // Attempt transfer from this contract to `to`.
        bool transferSucceeded;
        try c.transfer(to, transferAmount) {
            transferSucceeded = true;
        } catch {
            transferSucceeded = false;
        }

        // Read post-transfer values.
        uint256 postCallerBalance = c.balanceOf(address(this));
        uint256 postToBalance = c.balanceOf(to);

        // General rule:
        // 1. mint increases totalSupply and target balance by exactly mintAmount.
        // 2. transfer succeeds iff caller has sufficient balance and neither caller nor recipient is frozen.
        //    (freezeAccount is not called in this test, so both are unfrozen.)
        // 3. On success, caller balance decreases and recipient balance increases by exactly transferAmount.
        // 4. On failure, no balances change.
        bool expectedTransferSuccess = postTargetBalance >= transferAmount || preCallerBalance + mintAmount >= transferAmount;
        // Since mint went to target (which may or may not be this contract), the actual caller balance after mint is preCallerBalance plus any mint if target == address(this), otherwise unchanged.
        // To be precise, the caller's balance after mint is:
        uint256 callerBalanceAfterMint = preCallerBalance + (target == address(this) ? mintAmount : 0);
        expectedTransferSuccess = callerBalanceAfterMint >= transferAmount;

        assert(
            postTotalSupply >= preTotalSupply &&
            postTargetBalance >= preTargetBalance &&
            postTotalSupply == preTotalSupply + mintAmount &&
            postTargetBalance == preTargetBalance + mintAmount &&
            (
                (transferSucceeded &&
                 callerBalanceAfterMint >= transferAmount &&
                 postCallerBalance == callerBalanceAfterMint - transferAmount &&
                 postToBalance == preToBalance + transferAmount)
                ||
                (!transferSucceeded &&
                 callerBalanceAfterMint < transferAmount &&
                 postCallerBalance == callerBalanceAfterMint &&
                 postToBalance == preToBalance)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 transferAmount, uint256 freezeAmount) public {
        require(target != address(0));
        require(target != address(this));

        // Give this test contract tokens by minting to it. The test contract is the owner.
        c.mintToken(address(this), freezeAmount + transferAmount + 1);

        // Freeze the target address.
        c.freezeAccount(target, true);

        uint256 beforeSenderBalance = c.balanceOf(address(this));
        uint256 beforeTargetBalance = c.balanceOf(target);

        bool reverted;
        try c.transfer(target, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.balanceOf(address(this)) == beforeSenderBalance &&
            c.balanceOf(target) == beforeTargetBalance
        );
    }

    receive() external payable {}
}

